import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"第 7 课：第一次对话 —— 跑通第一个任务","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-2/lesson-7.md","filePath":"modules/module-2/lesson-7.md"}'),o={name:"modules/module-2/lesson-7.md"};function i(n,a,d,p,r,h){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="第-7-课-第一次对话-——-跑通第一个任务" tabindex="-1">第 7 课：第一次对话 —— 跑通第一个任务 <a class="header-anchor" href="#第-7-课-第一次对话-——-跑通第一个任务" aria-label="Permalink to &quot;第 7 课：第一次对话 —— 跑通第一个任务&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：完成 Codex 的第一次实际对话，体验从输入指令到获得结果的全过程<br> ⏱️ <strong>预计时长</strong>：20 分钟<br> 🎯 <strong>本节节奏</strong>：手把手实操</p></blockquote><hr><h2 id="一、最简单的开始-问一个问题" tabindex="-1">一、最简单的开始：问一个问题 <a class="header-anchor" href="#一、最简单的开始-问一个问题" aria-label="Permalink to &quot;一、最简单的开始：问一个问题&quot;">​</a></h2><p>打开 Codex，在对话框中输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今天 AI 圈有什么新闻？</span></span></code></pre></div><p>按回车（或点击发送）。</p><p>Codex 会联网搜索最新的 AI 相关新闻，并给你一份总结。你可能会看到类似这样的回复：</p><blockquote><p>以下是今天 AI 领域的几条重要新闻：</p><ol><li>OpenAI 发布了 GPT-5 的最新进展...</li><li>Google DeepMind 在 Nature 上发表了一篇新论文...</li><li>...</li></ol></blockquote><p>这就是 Codex 最基础的能力：<strong>联网检索 + 信息整理</strong>。</p><hr><h2 id="二、让它帮你做点实际的" tabindex="-1">二、让它帮你做点实际的 <a class="header-anchor" href="#二、让它帮你做点实际的" aria-label="Permalink to &quot;二、让它帮你做点实际的&quot;">​</a></h2><p>现在我们来做一个更实用的任务。</p><h3 id="任务-分析你电脑上的一个文件夹" tabindex="-1">任务：分析你电脑上的一个文件夹 <a class="header-anchor" href="#任务-分析你电脑上的一个文件夹" aria-label="Permalink to &quot;任务：分析你电脑上的一个文件夹&quot;">​</a></h3><ol><li>在 Codex 中打开一个文件夹作为工作区（比如你的&quot;下载&quot;文件夹，或者你专门创建的一个测试文件夹）</li><li>在对话框中输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我分析一下这个文件夹，统计一下里面有多少个文件，按文件类型分类看看各有多少个</span></span></code></pre></div></li><li>观察 Codex 的执行过程： <ul><li>它会列出文件夹中的文件</li><li>统计每种类型的数量</li><li>生成一个汇总报告</li></ul></li></ol><h3 id="你可能看到的输出" tabindex="-1">你可能看到的输出： <a class="header-anchor" href="#你可能看到的输出" aria-label="Permalink to &quot;你可能看到的输出：&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文件夹分析报告：</span></span>
<span class="line"><span>- 总文件数：47</span></span>
<span class="line"><span>- 按类型分类：</span></span>
<span class="line"><span>  - PDF 文档：12 个</span></span>
<span class="line"><span>  - JPEG 图片：8 个</span></span>
<span class="line"><span>  - MP4 视频：5 个</span></span>
<span class="line"><span>  - ZIP 压缩包：3 个</span></span>
<span class="line"><span>  - 其他：19 个</span></span></code></pre></div><hr><h2 id="三、进阶任务-整理文件夹" tabindex="-1">三、进阶任务：整理文件夹 <a class="header-anchor" href="#三、进阶任务-整理文件夹" aria-label="Permalink to &quot;三、进阶任务：整理文件夹&quot;">​</a></h2><p>如果你觉得只是&quot;看&quot;不够过瘾，让 Codex 帮你&quot;做&quot;：</p><h3 id="任务-整理杂乱的文件夹" tabindex="-1">任务：整理杂乱的文件夹 <a class="header-anchor" href="#任务-整理杂乱的文件夹" aria-label="Permalink to &quot;任务：整理杂乱的文件夹&quot;">​</a></h3><ol><li>准备一个包含各种文件的文件夹（如果没有，可以随便创建几个不同类型的文件）</li><li>在对话框中输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我整理这个文件夹，把同类文件放到同一个子文件夹里</span></span></code></pre></div></li><li>Codex 会： <ul><li>扫描所有文件</li><li>根据文件扩展名创建子文件夹（如 images/, documents/, videos/）</li><li>将文件移动到对应的子文件夹中</li></ul></li></ol><blockquote><p>⚠️ <strong>注意</strong>：在执行文件移动操作前，Codex 通常会先征求你的同意。这是默认权限模式的保护机制。</p></blockquote><hr><h2 id="四、感受-codex-如何一步步执行任务" tabindex="-1">四、感受 Codex 如何一步步执行任务 <a class="header-anchor" href="#四、感受-codex-如何一步步执行任务" aria-label="Permalink to &quot;四、感受 Codex 如何一步步执行任务&quot;">​</a></h2><p>当你输入指令后，Codex 的工作流程是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你输入指令 → Codex 理解意图 → Codex 读取相关文件 → Codex 制定计划 → Codex 执行操作 → 你审核结果</span></span></code></pre></div><p>每一步都有迹可循。你可以在 Codex 的执行日志中看到它的思考过程和操作步骤。</p><hr><h2 id="五、本节实操任务清单" tabindex="-1">五、本节实操任务清单 <a class="header-anchor" href="#五、本节实操任务清单" aria-label="Permalink to &quot;五、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 问 Codex 一个简单的问题（比如&quot;今天天气怎么样&quot;）</li><li>[ ] 设置一个文件夹为工作区</li><li>[ ] 让 Codex 分析该文件夹的内容</li><li>[ ] 让 Codex 整理该文件夹的文件</li><li>[ ] 观察 Codex 的执行日志</li></ul><hr><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>第一次对话</td><td>从简单问题开始，建立信心</td></tr><tr><td>文件夹分析</td><td>让 Codex 统计和分类文件</td></tr><tr><td>文件夹整理</td><td>让 Codex 自动归类文件</td></tr><tr><td>执行流程</td><td>理解 → 计划 → 执行 → 审核</td></tr></tbody></table><hr><h2 id="七、下一步" tabindex="-1">七、下一步 <a class="header-anchor" href="#七、下一步" aria-label="Permalink to &quot;七、下一步&quot;">​</a></h2><p><a href="./../module-3/lesson-8.html">→ 进入模块三：核心功能</a></p>`,38)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
